declare(strict_types=1);
// Read-only analysis of accepted reports. Missing evidence never becomes zero.
function dr_labels(): array {return ['formation'=>'Modulo','mentality'=>'Mentalità','tackling_style'=>'Contrasti / aggressività','pressing'=>'Pressing','tempo'=>'Ritmo','width'=>'Ampiezza','passing_style'=>'Passaggi','attacking_style'=>'Stile di attacco','wide_play'=>'Gioco sulle fasce','creativity'=>'Creatività','fluidity'=>'Fluidità','defensive_line'=>'Linea difensiva','forwards_instruction'=>'Istruzioni attaccanti','use_playmaker'=>'Regista attivo','use_target_man'=>'Uomo bersaglio attivo','counter_attack'=>'Contropiede','tight_marking'=>'Marcatura stretta','sweeper_keeper'=>'Portiere libero','men_behind_ball'=>'Uomini dietro la palla'];}
function dr_value(mixed $v): ?string {
    if(!is_scalar($v))return null;$v=trim((string)$v);if($v===''||in_array(strtolower($v),['null','unknown','n/a','-'],true))return null;
    return ['yes'=>'Sì','si'=>'Sì','sì'=>'Sì','no'=>'No','balanced'=>'Bilanciato','bold'=>'Audace','normal'=>'Normale','fast'=>'Veloce','slow'=>'Lento','hard'=>'Duro','easy'=>'Leggero','attacking'=>'Offensivo','defensive'=>'Difensivo','mixed'=>'Misto','direct'=>'Diretto','short'=>'Corto','long'=>'Lungo','high'=>'Alto','deep'=>'Basso','all over'=>'Ovunque'][mb_strtolower($v,'UTF-8')]??mb_substr($v,0,100,'UTF-8');
}
function dr_zero(): array {return ['n'=>0,'won'=>0,'drawn'=>0,'lost'=>0,'gf'=>0,'ga'=>0,'pos_sum'=>0,'pos_n'=>0,'shot_sum'=>0,'shot_n'=>0];}
function dr_result(array &$s,array $m,string $side,array $teams): void {
    $other=$side==='home'?'away':'home';$gf=(int)$m[$side.'_score'];$ga=(int)$m[$other.'_score'];$s['n']++;$s['won']+=(int)($gf>$ga);$s['drawn']+=(int)($gf===$ga);$s['lost']+=(int)($gf<$ga);$s['gf']+=$gf;$s['ga']+=$ga;
    foreach(['possession'=>'pos','total_shots'=>'shot'] as $field=>$key)if(is_numeric($teams[$side][$field]??null)){$s[$key.'_sum']+=(float)$teams[$side][$field];$s[$key.'_n']++;}
}
function dr_snapshot(array $all,string $side,int $minute=0): ?array {
    $found=[];foreach($all as $t)if(is_array($t)&&($t['team_side']??'')===$side&&isset($t['snapshot_minute'])&&is_numeric($t['snapshot_minute'])&&(int)$t['snapshot_minute']===$minute){ksort($t);$found[json_encode($t)]=$t;}
    return count($found)===1?array_values($found)[0]:null;
}
function dr_clock(mixed $v): ?array {
    if(!is_scalar($v)||!preg_match('/^(\d{1,3})(?:\+(\d{1,2}))?$/D',trim((string)$v),$p))return null;
    $base=(int)$p[1];$minute=$base+(int)($p[2]??0);if($base>120||$minute>150)return null;
    $bucket=$base<=15?'0–15':($base<=30?'16–30':($base<=45?'31–45+':($base<=60?'46–60':($base<=75?'61–75':($base<=90?'76–90+':'Supplementari')))));
    // A period boundary sorts stoppage time before the following half.
    $order=$base*100+(int)($p[2]??0);return compact('minute','bucket','order');
}
function dr_goals(array $players,array $m): ?array {
    $goals=[];$totals=['home'=>0,'away'=>0];$seen=[];
    foreach($players as $p){$side=$p['team_side']??'';$id=$p['sm_player_id']??0;if(!isset($totals[$side])||(int)$id<1||isset($seen[$side.'|'.$id]))continue;$seen[$side.'|'.$id]=true;
        foreach(['goal_minutes'=>['goals',$side],'own_goal_minutes'=>['own_goals',$side==='home'?'away':'home']] as $field=>[$count,$benefit]){
            $minutes=$p[$field]??[];if(!is_array($minutes))return null;$expected=max((int)($p[$count]??0),count($minutes));if($expected!==count($minutes))return null;
            foreach($minutes as $minute){$clock=dr_clock($minute);if(!$clock)return null;$goals[]=$clock+['side'=>$benefit];$totals[$benefit]++;}
        }
    }
    if($totals['home']!==(int)$m['home_score']||$totals['away']!==(int)$m['away_score'])return null;
    usort($goals,fn($a,$b)=>$a['order']<=>$b['order']);return $goals;
}
