    $minutes=[];foreach($tactics as $t)if(is_array($t)&&($t['team_side']??'')===$side&&is_numeric($t['snapshot_minute']??null)&&(int)$t['snapshot_minute']>=0)$minutes[(int)$t['snapshot_minute']]=true;ksort($minutes);$prev=null;$changed=false;
    foreach(array_keys($minutes) as $minute){$next=dr_snapshot($tactics,$side,$minute);if(!$next){$prev=null;continue;}if($prev){$diff=[];foreach(dr_labels() as $f=>$label){$before=dr_value($prev[$f]??null);$after=dr_value($next[$f]??null);if($before!==null&&$after!==null&&$before!==$after)$diff[]=$label.': '.$before.' → '.$after;}if($diff){$changed=true;$d['changes'][]=['date'=>$m['date'],'minute'=>$minute,'description'=>implode(' · ',$diff),'match'=>nr_event($m,0,$side)];}}$prev=$next;}$d['changed_games']+=(int)$changed;
