        $d['players'][$pid]??=['id'=>$pid,'name'=>$p['player_name']??$pid,'played'=>0,'starts'=>0,'subs'=>0,'off'=>0,'minutes'=>0,'known'=>0,'goals'=>0,'assists'=>0,'mom'=>0,'yellow'=>0,'red'=>0,'rating_sum'=>0,'rated'=>0,'captain'=>0];$pl=&$d['players'][$pid];$pl['played']++;$pl['starts']+=(int)$u['starter'];$pl['subs']+=(int)!$u['starter'];$pl['off']+=(int)(nexus_roster_minute($p['sub_off_minute']??null)!==null);$pl['captain']+=(int)((int)($p['captain']??0)>0);foreach(['goals','assists','mom','yellow','red'] as $f)$pl[$f]+=$u[$f];if($u['minutes']!==null){$pl['minutes']+=$u['minutes'];$pl['known']++;}if($u['rating']!==null){$pl['rating_sum']+=$u['rating'];$pl['rated']++;}$red=$red||$u['red']>0;unset($pl);
