function dr_metric(string $label,mixed $value,string $unit='',?int $sample=null): array {return compact('label','value','unit','sample');}
function dr_table(string $title,array $columns,array $rows,string $note=''): array {return compact('title','columns','rows','note');}
function dr_results(array $groups,callable $label): array {
    uasort($groups,fn($a,$b)=>$b['n']<=>$a['n']);$rows=[];foreach($groups as $key=>$s)$rows[]=[ $label((string)$key),$s['n'],$s['won'],$s['drawn'],$s['lost'],round(100*$s['won']/$s['n'],1).'%', $s['gf'].'–'.$s['ga'],round((3*$s['won']+$s['drawn'])/$s['n'],2),$s['pos_n']?round($s['pos_sum']/$s['pos_n'],1).'% ('.$s['pos_n'].')':'—',$s['shot_n']?round($s['shot_sum']/$s['shot_n'],1).' ('.$s['shot_n'].')':'—'];return $rows;
